mapper.update:
update corgi_user_login
set im_id = #{userLogin.imId}
where id = #{userLogin.userId}

update corgi_user_login
set im_id = #{userLogin.imId},
tel_no = #{userLogin.telNo}
where id = #{userLogin.userId}

update corgi_user_detail
set `nickname` = #{nickname}, check_nickname = #{checkNickname}
where user_id = #{userId}

update corgi_user_detail
set avatar_status = #{status}
where avatar_data_id = #{dataId}

update corgi_user_detail
set avatar = null, avatar_status = null, avatar_data_id = null
where avatar_data_id = #{dataId}

update corgi_user_position set lat = #{position.lat}, lng = #{position.lng}, uptime = #{position.uptime},locate_type = #{position.locateType}, pt=point(#{position.lng},#{position.lat}),
real_lat = #{position.realLat}, real_lng = #{position.realLng},
`version` = #{position.version}
where user_id = #{position.userId}

update corgi_user_position set uptime = #{position.uptime},
real_lat = #{position.realLat}, real_lng = #{position.realLng}, locate_type = #{position.locateType},
`version` = #{position.version}
where user_id = #{position.userId}

mapper.select:
select p.user_id from corgi_user_position p
left join corgi_user_detail d on p.user_id = d.user_id

    join corgi_user_follow f1 on f1.user_id = #{range.userId} and f1.follow_user_id = p.user_id and f1.is_deleted = '0'


    join corgi_user_follow f2 on f2.follow_user_id = #{range.userId} and f2.user_id = p.user_id and f2.is_deleted = '0'

where p.lat >= #{range.beginLat} and p.lat <= #{range.endLat}
and p.lng >= #{range.beginLng} and p.lng <= #{range.endLng}

    and d.height >= #{range.startHeight}


    and d.height <= #{range.endHeight}


    and d.weight >= #{range.startWeight}


    and d.weight <= #{range.endWeight}


    and d.relation in ${range.relation}


    and d.role in ${range.role} and d.hide_role != '1'


    and d.group in ${range.group} and d.hide_group != '1'

select
d.user_id userId,
d.nickname nickname,
d.check_nickname checkNickname,
d.avatar avatar,
d.avatar_status avatarStatus,
d.role role,
d.hide_role hideRole,
d.group `group`,
d.hide_group `hideGroup`,
d.hide_prefer_group `hidePreferGroup`,
d.con con,
d.relation,
d.desc,
d.check_desc checkDesc,
l.im_id imId,
l.tel_no telNo,
p.lat lat,
p.lng lng,
p.uptime `time`,
l.ctime createTime,
d.check_status checkStatus
from corgi_user_detail d
left join corgi_user_login l on l.id = d.user_id
left join corgi_user_position p on p.user_id = d.user_id
where 1=1

    and right(p.version,5) >= #{userDetail.version}


    and UPPER(`nickName`) like UPPER(concat('%',#{userDetail.nickname},'%'))


    and l.tel_no = #{userDetail.telNo}


    and `height` = #{userDetail.height}


    and `weight` = #{userDetail.weight}


    and `desc` like concat('%',#{userDetail.desc},'%')


    and `role` = #{userDetail.role}


    and `character` = #{userDetail.character}


    and `group` = #{userDetail.group}


    and `birthday` = #{userDetail.birthday}


    and `city` = #{userDetail.city}


    and `con` = #{userDetail.con}


    and `relation` = #{userDetail.relation}


    and d.user_id = #{userDetail.userId}


    and d.check_status = #{userDetail.checkStatus}

order by d.user_id
limit #{start},#{size}

select
count(1)
from corgi_user_detail d
left join corgi_user_login l on l.id = d.user_id
where 1=1

    and `nickName` like concat('%',#{userDetail.nickname},'%')


    and l.tel_no = #{userDetail.telNo}


    and `height` = #{userDetail.height}


    and `weight` = #{userDetail.weight}


    and `desc` like concat('%',#{userDetail.desc},'%')


    and `role` = #{userDetail.role}


    and `relation` = #{userDetail.relation}


    and `character` = #{userDetail.character}


    and `group` = #{userDetail.group}


    and `birthday` = #{userDetail.birthday}


    and `city` = #{userDetail.city}


    and `con` = #{userDetail.con}


    and d.user_id = #{userDetail.userId}


    and d.check_status = #{userDetail.checkStatus}
